import{_ as e,o as t,c as i,e as r}from"./app-6be1f847.js";const o="/vuepress_blog/assets/springSecurity_default_filters-6e3323aa.png",s="/vuepress_blog/assets/spingSecurity_authentication_token-18e66d3b.png",n="/vuepress_blog/assets/springSecurity_providers-8fb99eec.png",c="/vuepress_blog/assets/jwt_username_password_authentication-6342bc3b.png",a={},l=r('<p>Spring Security 的核心是一个<strong>过滤器链（FilterChain）</strong>，每个请求都会经过一系列过滤器处理，最终实现认证和授权。主要分为两大流程：</p><ol><li><strong>认证流程</strong>：验证用户身份（如用户名密码、令牌等）。</li><li><strong>授权流程</strong>：检查用户是否有权限访问特定资源。</li></ol><p><strong>关键类与接口</strong>：</p><ol><li><p><strong>过滤器（Filter）</strong>：</p><ul><li><code>UsernamePasswordAuthenticationFilter</code>：处理表单登录请求。</li><li><code>BasicAuthenticationFilter</code>：处理HTTP Basic认证。</li><li><code>OAuth2LoginAuthenticationFilter</code>：处理OAuth2登录。</li></ul></li><li><p><strong>认证管理器（AuthenticationManager）</strong>：</p><ul><li><code>ProviderManager</code>：默认实现，委托给多个<code>AuthenticationProvider</code>。</li></ul></li><li><p><strong>认证提供者（AuthenticationProvider）</strong>：</p><ul><li><code>DaoAuthenticationProvider</code>：基于数据库的认证，使用<code>UserDetailsService</code>加载用户信息。</li></ul></li><li><p><strong>用户信息（UserDetails）</strong>：</p><ul><li><code>UserDetailsService</code>：加载用户信息的接口（如从数据库查询）。</li><li><code>UserDetails</code>：用户信息的封装（包含用户名、密码、权限等）。</li></ul></li><li><p><strong>安全上下文（SecurityContext）</strong>：</p><ul><li><code>SecurityContextHolder</code>：存储当前认证用户的上下文。</li><li><code>Authentication</code>：认证信息的接口，包含用户主体、凭证、权限等。</li></ul></li></ol><h2 id="springsecurity-过滤器链" tabindex="-1"><a class="header-anchor" href="#springsecurity-过滤器链" aria-hidden="true">#</a> SpringSecurity 过滤器链</h2><p>springSecurity 过滤器链可以通过查看 <code>DefaultSecurityFilterChain</code> 这个类中的 <code>List&lt;Filter&gt; filters</code> 属性得到，默认如下图所示</p><p><img src="'+o+'" alt="springSecurity_default_filters"></p><h2 id="springsecurity-authentication" tabindex="-1"><a class="header-anchor" href="#springsecurity-authentication" aria-hidden="true">#</a> SpringSecurity Authentication</h2><p>springSecurity Authentication</p><p><img src="'+s+'" alt="springSecurity_authentication_token"></p><p>下面是账号密码认证关键类，结合上图 <code>UserNamePasswordAuthenticationToken</code> ，即可完成认证</p><p><img src="'+n+'" alt="springSecurity_providers"></p><p>下图是一个常见的 <code>jwt + username + password</code> 认证流程</p><p><img src="'+c+'" alt="jwt_username_password_authentication"></p><p>如果需要<strong>自定义其它认证方式</strong>，则需要 实现 <code>AuthenticationProvider</code> 接口，自定义 <code>authenticate</code> 方法，并将自定义的 provider 注册到 <code>ProviderManager</code> 上， 还需要 继承 <code>AbstractAuthenticationToken</code></p>',15),p=[l];function d(u,g){return t(),i("div",null,p)}const h=e(a,[["render",d],["__file","/home/runner/work/vuepress_blog/vuepress_blog/docs/.vuepress/.temp/pages/java/springSecurity/springSecurity1.html.vue"]]);export{h as default};
